package main

import (
	"crypto/rsa"
	"crypto/x509"
	"encoding/pem"
	"fmt"
	"io/ioutil"
	"net/http"
	"sync"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

const (
	maxRetries     = 3
	retryDelay     = 500 * time.Millisecond
	rateLimit      = 10
	rateLimitWindow = time.Minute
)

type RateLimiter struct {
	mu       sync.Mutex
	tokens   map[string][]time.Time
}

func NewRateLimiter() *RateLimiter {
	return &RateLimiter{tokens: make(map[string][]time.Time)}
}

func (rl *RateLimiter) Allow(clientID string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	now := time.Now()
	windowStart := now.Add(-rateLimitWindow)
	var valid []time.Time
	for _, t := range rl.tokens[clientID] {
		if t.After(windowStart) {
			valid = append(valid, t)
		}
	}
	if len(valid) >= rateLimit {
		return false
	}
	rl.tokens[clientID] = append(valid, now)
	return true
}

type FirmwareAuthService struct {
	publicKey  *rsa.PublicKey
	limiter    *RateLimiter
	keyBytes   []byte
}

func NewFirmwareAuthService(pubKeyPath string) (*FirmwareAuthService, error) {
	keyData, err := ioutil.ReadFile(pubKeyPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read public key: %w", err)
	}
	block, _ := pem.Decode(keyData)
	if block == nil {
		return nil, fmt.Errorf("failed to decode PEM block")
	}
	pub, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse public key: %w", err)
	}
	rsaPub, ok := pub.(*rsa.PublicKey)
	if !ok {
		return nil, fmt.Errorf("key is not RSA")
	}
	return &FirmwareAuthService{
		publicKey: rsaPub,
		limiter:   NewRateLimiter(),
		keyBytes:  keyData,
	}, nil
}

func (s *FirmwareAuthService) getVerificationKey(token *jwt.Token) (interface{}, error) {
	switch token.Method.Alg() {
	case "RS256", "RS384", "RS512":
		return s.publicKey, nil
	case "HS256", "HS384", "HS512":
		return s.keyBytes, nil
	default:
		return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
	}
}

func (s *FirmwareAuthService) ValidateToken(tokenString string) (*jwt.MapClaims, error) {
	token, err := jwt.Parse(tokenString, s.getVerificationKey)
	if err != nil {
		return nil, fmt.Errorf("token validation failed: %w", err)
	}
	if !token.Valid {
		return nil, fmt.Errorf("invalid token")
	}
	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		return nil, fmt.Errorf("invalid claims format")
	}
	if dev, exists := claims["device_class"]; exists {
		if devStr, ok := dev.(string); ok && devStr != "iot_sensor" && devStr != "iot_actuator" {
			return nil, fmt.Errorf("unauthorized device class")
		}
	}
	return &claims, nil
}

func (s *FirmwareAuthService) AuthenticateWithRetry(tokenString, clientID string) (*jwt.MapClaims, error) {
	if !s.limiter.Allow(clientID) {
		return nil, fmt.Errorf("rate limit exceeded for client %s", clientID)
	}
	var lastErr error
	for attempt := 0; attempt < maxRetries; attempt++ {
		claims, err := s.ValidateToken(tokenString)
		if err == nil {
			return claims, nil
		}
		lastErr = err
		time.Sleep(retryDelay)
	}
	return nil, fmt.Errorf("authentication failed after %d retries: %w", maxRetries, lastErr)
}

func (s *FirmwareAuthService) HandleFirmwareUpdate(w http.ResponseWriter, r *http.Request) {
	tokenString := r.Header.Get("Authorization")
	if tokenString == "" {
		http.Error(w, "missing authorization", http.StatusUnauthorized)
		return
	}
	if len(tokenString) > 7 && tokenString[:7] == "Bearer " {
		tokenString = tokenString[7:]
	}
	clientID := r.Header.Get("X-Device-ID")
	if clientID == "" {
		http.Error(w, "missing device ID", http.StatusBadRequest)
		return
	}
	claims, err := s.AuthenticateWithRetry(tokenString, clientID)
	if err != nil {
		http.Error(w, err.Error(), http.StatusUnauthorized)
		return
	}
	fmt.Fprintf(w, "Firmware update authorized for device: %v", (*claims)["sub"])
}

func main() {
	service, err := NewFirmwareAuthService("/etc/iot/public_key.pem")
	if err != nil {
		panic(err)
	}
	http.HandleFunc("/api/v1/firmware/update", service.HandleFirmwareUpdate)
	http.ListenAndServeTLS(":8443", "/etc/iot/server.crt", "/etc/iot/server.key", nil)
}
